css:
.info{
    display:flex;
    font-size:12;
}

.info>div{
    flex:1;
}


.info-detail tr{
    background-color:#ccc;
    border-bottom : 10px solid white;
    font-size:12;
}

.delivery-detail>table{
    width:62%;
    border-top:5px solid #ccc;  
    font-size:12px;
}

.item-detail>table{
     font-size:12px;
     width:100%;
}

.item-detail thead{
     background-color:#ccc;
}

.total>table{
    width:50%;
    font-size:12px;
}

.total{
    display:flex;
    align-items:flex-end;
    justify-content:flex-end;
    margin-top:30px;
}

.total td:last-child{
    text-align:right;
}

.total tr:last-child{
    background-color:#ccc;
}
